@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-inline-block">
    <span class="fs-4">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star-rating-star"
                  @key="star"
                  data-selected="@(star <= selectedRating ? "true" : "false")"
                  data-hovered="@(star <= hoveredRating ? "true" : "false")"
                  @onclick="() => SubmitRating(star)"
                  @onmouseover="() => hoveredRating = star"
                  @onmouseout="() => hoveredRating = 0">
                @(star <= (hoveredRating > 0 ? hoveredRating : selectedRating) ? "★" : "☆")
            </span>
        }
    </span>

    @if (submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }

    <div class="text-muted small mt-1">
        Average: @currentAverage.ToString("0.0") / 5 (@ratingCount ratings)
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentAverage { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int selectedRating;
    private int hoveredRating;
    private bool submitted;
    private double currentAverage;
    private int ratingCount;

    protected override void OnParametersSet()
    {
        currentAverage = CurrentAverage;
        ratingCount = RatingCount;
    }

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            currentAverage = recipe.AverageRating;
            ratingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

