toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<nav>
    <a href="/">← Back to Home</a>
</nav>

<h1 class="mt-3">Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (submittedRecipeId is not null)
{
    <div class="alert alert-success">
        Recipe submitted successfully!
        <a href="recipe/@submittedRecipeId">View your recipe →</a>
    </div>
}

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="mb-3">
        <label class="form-label">Title</label>
        <InputText @bind-Value="Model!.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => Model!.Title" />
    </div>

    <div class="mb-3">
        <label class="form-label">Category</label>
        <InputSelect @bind-Value="Model!.Category" class="form-select">
            <option value="">-- Select a category --</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => Model!.Category" />
    </div>

    <div class="mb-3">
        <label class="form-label">Summary</label>
        <InputText @bind-Value="Model!.Summary" class="form-control" placeholder="Brief description of the dish" />
        <ValidationMessage For="() => Model!.Summary" />
    </div>

    <div class="mb-3">
        <label class="form-label">Ingredients (one per line)</label>
        <InputTextArea @bind-Value="Model!.Ingredients" class="form-control" rows="6"
                       placeholder="1 cup flour&#10;2 eggs&#10;1/2 cup sugar" />
        <ValidationMessage For="() => Model!.Ingredients" />
    </div>

    <div class="mb-3">
        <label class="form-label">Steps (one per line)</label>
        <InputTextArea @bind-Value="Model!.Steps" class="form-control" rows="6"
                       placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
        <ValidationMessage For="() => Model!.Steps" />
    </div>

    <button type="submit" class="btn btn-success" disabled="@isSubmitting">
        @(isSubmitting ? "Submitting..." : "Submit Recipe")
    </button>
</EditForm>

@code {
    private SubmitRecipeModel? Model { get; set; }

    private bool isSubmitting;
    private int? submittedRecipeId;

    protected override void OnInitialized() => Model ??= new();

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        try
        {
            await Task.Yield();

            var recipe = new RecipeShare.Services.Recipe
            {
                Title = Model!.Title!,
                Category = Model.Category!,
                Summary = Model.Summary ?? "",
                Ingredients = Model.Ingredients!,
                Steps = Model.Steps!,
            };

            RecipeService.AddRecipe(recipe);
            submittedRecipeId = recipe.Id;
            Model = new();
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

